 if(!width)return 0;
 if(e->kind==10&&e->packing==2){float value;
 if(!table_message_float(&s->input,e,&value))return 0;
 lo=table_float_to_bits(value);
 }
 else if(!table_message_number(&s->input,e,&lo,&hi))return 0;
