/* Retention requires a variable root loaded into a region (SPEC-TABLES section 6.6). */
#define wide_blob_load_retain(...) ((void)sizeof(struct { int retention_requires_variable_region_root : -1; }))
/* Retention requires a variable root loaded into a region (SPEC-TABLES section 6.6). */
